1157	func readTrailBodyStdin(stdin io.Reader) (string, bool, error) {
1158		if stdin == nil {
1159			return "", false, errors.New("no stdin available to read the body from")
1160		}
1161		data, err := io.ReadAll(stdin)
1162		if err != nil {
1163			return "", false, fmt.Errorf("read body from stdin: %w", err)
1164		}
1165		return string(data), true, nil
1166	}
